  if(chordMode)fist.update(null,time);
  if(time-lastSeen>250)setText('cameraState','Strumming hand not visible');
  if(time-lastSeen>650){lastPoint=null;stroke=createSweepState();calibration=[];setText('tracking',zone?(chordMode?'Bring your right hand back to continue.':'Bring your whole hand back into view to continue.'):(chordMode?'Hold your right hand still on the right; choose chords with your left hand on the left.':'Bring your strumming hand into view. Lower your other hand for now.'))}
