function loadDetector(){if(detectorReady)return Promise.resolve();return new Promise((resolve,reject)=>{worker=new Worker(`tracker.js?v=42&hands=${chordMode?2:1}`);const timeout=setTimeout(()=>reject(Error('Hand model timed out. Please try again.')),30000);worker.onmessage=e=>{if(e.data.type==='ready'){clearTimeout(timeout);detectorReady=true;resolve()}else if(e.data.type==='result'){if(e.data.epoch!==cameraEpoch)return;pending=false;trackingBudget.observe(Math.max(e.data.durationMs??0,performance.now()-lastDetection),performance.now());if(cameraRunning)hands(e.data.result,e.data.timestamp)}else if(e.data.type==='error'){if(e.data.epoch!==undefined&&e.data.epoch!==cameraEpoch)return;pending=false;clearTimeout(timeout);reject(Error(e.data.message));if(cameraRunning){toast('Hand tracking stopped. Please start it again.');stopCamera()}}};worker.onerror=()=>{clearTimeout(timeout);reject(Error('Could not load the hand-tracking model.'))}})}
