$('camera').onclick=async()=>{if(cameraRunning){stopCamera();return}if(loadingCamera)return;loadingCamera=true;const token=++cameraEpoch;$('camera').disabled=true;try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera access is unavailable in this browser. Use Space to play.');await initAudio();stream=await navigator.mediaDevices.getUserMedia({video:{width:{ideal:640},height:{ideal:480},frameRate:{ideal:30,max:30}},audio:false});$('video').srcObject=stream;await $('video').play();await loadDetector();if(token!==cameraEpoch)return;cameraRunning=true;pending=false;lastVideo=-1;trackingBudget.reset();$('canvas').width=320;$('canvas').height=Math.max(1,Math.round($('video').videoHeight*320/$('video').videoWidth));$('empty').hidden=true;$('camera').textContent='Stop camera';$('cameraState').textContent=chordMode?'Close your right hand to prepare.':'Calibrating…';$('tracking').textContent=chordMode?'Keep your right hand on the right. Close it, then open naturally.':'Keep your whole hand in view and hold still for one second.';scheduleCameraFrame()}catch(e){stopCamera();if(!detectorReady){worker?.terminate();worker=null}toast(e.name==='NotAllowedError'?'Allow camera access to use gestures, or use Space to play.':e.message)}finally{loadingCamera=false;$('camera').disabled=false}};
function chooseChord(chord){chosenChord=chord;for(const card of $('chordCards').children){const active=card.dataset.chord===chord;card.setAttribute('aria-pressed',String(active));}paint(true)}
function renderChordCards(){$('chordCards').replaceChildren();$('chordCards').classList.toggle('two-chords',!!session.song.beginner);for(const [i,chord] of choices().entries()){const card=document.createElement('button');card.dataset.chord=chord;card.setAttribute('aria-pressed',String(chord===chosenChord));card.innerHTML=`<small>Left hand ${i===5?'🤙 6':i+1} · Keyboard ${i+1}</small><strong>${session.song.groupNames?.[chord]??chord}</strong><span>${session.song.assisted?`Show  ${i+1} fingers · Hold for 8 beats`:i===5?'Show 6 🤙':`Show  ${i+1} fingers` }</span>`;card.onclick=()=>chooseChord(chord);$('chordCards').append(card)}
}
async function changeMode(next){if(next===chordMode||loadingCamera)return;const reopen=cameraRunning;if(!chordMode)easySongId=$('song').value;stopCamera();worker?.terminate();worker=null;detectorReady=false;pending=false;chordMode=next;selector.reset();fist.reset();demo=false;session.setSong(next?chordSongs.find(s=>s.id===chordSongId):songs.find(s=>s.id===easySongId));recordingPlayer?.reset();chosenChord=session.song.chords[0].chord;shownDiagram='';document.body.classList.toggle('chord-mode',next);$('stageCoach').hidden=!next;$('chordCards').hidden=!next;$('chordGuide').hidden=!next;$('song').disabled=false;$('song').replaceChildren();for(const song of (next?chordSongs:songs)){const option=document.createElement('option');option.value=song.id;option.textContent=next?(song.menuLabel??(song.relaxed?'Relaxed six-chord practice':'Six-chord practice')):`${song.level??'Beginner'} · ${song.title}`;$('song').append(option);}$('song').value=next?chordSongId:easySongId;selector=createChordSelector(choices());$('easyMode').setAttribute('aria-pressed',String(!next));$('chordMode').setAttribute('aria-pressed',String(next));leftNumber=null;leftVisible=false;document.querySelector('#empty h2').textContent=next?'Left: choose a chord. Right: close, then open.':'Bring your hand into view';document.querySelector('#empty p').innerHTML=next?'Keep one hand on each side of the frame.<br>Show 1–5 fingers with your left hand; use 🤙 for 6. Close and open your right hand to play.<br>You can also use chord cards and Space.':'Keep your whole strumming hand in view. Raise it, then strum down clearly.<br>Hold still for a second to calibrate.<br>No camera? Use Space or the play-note button.';setText('modeHint',next?'Left: show 1–5 fingers; 🤙 for 6. Right: close, then open once to play.':'Raise your hand to prepare, then strum down.');document.querySelector('.rule').textContent=next?'Choose left-hand chord numbers. Close and open your right hand once per beat. You can also use keys 1–6 and Space.':'Raise your hand, then make a clear downstroke. Small shakes and sideways moves do not trigger notes.';chooseChord(session.song.chords[0].chord);selected();if(reopen)await $('camera').onclick();}
$('stageCoach').addEventListener('click',event=>{const row=event.target.closest('button[data-chord]');if(row)chooseChord(row.dataset.chord)});
$('easyMode').onclick=()=>changeMode(false);$('chordMode').onclick=()=>changeMode(true);
document.addEventListener('keydown',e=>{if(chordMode&&!e.repeat&&/^[1-6]$/.test(e.key)&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName)){const chord=choices()[Number(e.key)-1];if(chord)chooseChord(chord);}});
